blocks.mermaid:
flowchart TD
  A["Fila propuesta para insertar"] --> B{"¿Choca con el índice único del objetivo del conflicto?"}
  B -- "No" --> I["Se inserta"]
  B -- "Sí" --> C{"¿Qué acción pediste?"}
  C -- "DO NOTHING" --> N["Se omite en silencio"]
  C -- "DO UPDATE" --> W{"¿Se cumple el WHERE de DO UPDATE?"}
  W -- "Sí o no hay WHERE" --> U["Se actualiza la fila existente usando EXCLUDED"]
  W -- "No" --> S["La fila existente queda igual, pero bloqueada"]
  I --> R["Cuenta en INSERT 0 n y sale en RETURNING"]
  U --> R

